create table public.strategy_attribution_contexts(id uuid primary key default gen_random_uuid(),attribution_key text not null unique,contract_version text not null,status text not null check(status in('KNOWN','UNKNOWN')),strategy_definition_id uuid references public.strategy_definitions(id),strategy_version integer,validation_run_id uuid references public.strategy_validation_runs(id),runtime_assessment_id uuid references public.strategy_runtime_assessments(id),information_cutoff_at timestamptz not null,available_at timestamptz not null,payload_hash text not null,created_at timestamptz not null default now(),check(available_at<=information_cutoff_at),check((status='UNKNOWN' and strategy_definition_id is null and strategy_version is null and validation_run_id is null and runtime_assessment_id is null)or(status='KNOWN' and strategy_definition_id is not null and strategy_version is not null and validation_run_id is not null)));
create trigger strategy_attribution_contexts_immutable before update or delete on public.strategy_attribution_contexts for each row execute function public.prevent_execution_history_mutation();alter table public.strategy_attribution_contexts enable row level security;create policy "public read strategy attribution" on public.strategy_attribution_contexts for select using(true);grant select on public.strategy_attribution_contexts to anon,authenticated;grant all on public.strategy_attribution_contexts to service_role;
alter table public.trade_proposals add column strategy_attribution_id uuid references public.strategy_attribution_contexts(id);alter table public.trade_eligibility_evaluations add column strategy_attribution_id uuid references public.strategy_attribution_contexts(id);alter table public.execution_intents add column strategy_attribution_id uuid references public.strategy_attribution_contexts(id);alter table public.execution_orders add column strategy_attribution_id uuid references public.strategy_attribution_contexts(id);alter table public.execution_fills add column strategy_attribution_id uuid references public.strategy_attribution_contexts(id);
create index trade_proposals_strategy_attribution_idx on public.trade_proposals(strategy_attribution_id,created_at desc);create index execution_intents_strategy_attribution_idx on public.execution_intents(strategy_attribution_id,created_at desc);create index execution_orders_strategy_attribution_idx on public.execution_orders(strategy_attribution_id,created_at desc);create index execution_fills_strategy_attribution_idx on public.execution_fills(strategy_attribution_id,created_at desc);
